#include <iostream>
#include <iomanip>
#include <ctime>

void format_timestamp(std::ostream& os, uint64_t timestamp) {
    std::time_t time_t = timestamp / 1000000;
    auto gmtime = std::gmtime(&time_t);
    char buffer[32];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %T.", gmtime); // Corrected format string
    char microseconds[8]; // Increased buffer size to 8 to accommodate null terminator
    snprintf(microseconds, sizeof(microseconds), "%06llu", timestamp % 1000000); // Use snprintf to prevent buffer overflow
    os << '[' << buffer << microseconds << ']';
}

int main() {
    uint64_t timestamp = 1633072800000000; // Example timestamp
    format_timestamp(std::cout, timestamp);
    return 0;
}
